// trailCost is the width of the pills RenderTabs draws for labels.
func trailCost(labels []string) int {
	if len(labels) == 0 {
		return 0
	}
	cost := len(labels) - 1
	for _, l := range labels {
		cost += ansi.StringWidth(l) + 2
	}
	return cost
}

func trailTabs(labels []string) []TabItem {
